mapper.select:
WITH riskcatlist AS ( SELECT g.riskcatname as name, ROW_NUMBER() OVER (PARTITION BY r.riskid,r.riskid order by r.riskid ) AS rn from TBL_RISK_ASSPLAN_RISK r left join TBL_RISK_RISKMARKING a on a.assriskid=r.assriskid left join TBL_RISK_ASSPLAN p on p.assplanid=r.assplanid left join TBL_RISK s on s.riskid=r.riskid left join TBL_RISKCATEGORY g on g.riskcatid=s.riskcatid where s.unit is not null and r.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid) and ( s.riskstatus !=0 or s.riskstatus is null)
and s.unit=#{company}
and a.asssatus=2 and g.riskcatname is not null ) SELECT name,count(1) as value FROM riskcatlist WHERE rn = 1 group by name;

WITH riskcatlist AS ( SELECT s.riskname as name, ROW_NUMBER() OVER (PARTITION BY r.riskid,r.riskid order by r.riskid ) AS rn from TBL_RISK_ASSPLAN_RISK r left join TBL_RISK_RISKMARKING a on a.assriskid=r.assriskid left join TBL_RISK_ASSPLAN p on p.assplanid=r.assplanid left join TBL_RISK s on s.riskid=r.riskid where s.unit is not null and a.asssatus=2 and s.riskname is not null and r.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid) and ( s.riskstatus !=0 or s.riskstatus is null)
and s.unit=#{company}
) SELECT name,count(1) as value FROM riskcatlist WHERE rn = 1 group by name;

WITH riskcatlist AS ( SELECT s.riskcatname as name, ROW_NUMBER() OVER (PARTITION BY r.riskid,r.riskid order by r.riskid ) AS rn from TBL_RISK_ASSPLAN_RISK r left join TBL_RISK_RISKMARKING a on a.assriskid=r.assriskid left join TBL_RISK_ASSPLAN p on p.assplanid=r.assplanid left join TBL_RISK s on s.riskid=r.riskid where s.unit is not null and a.asssatus=2 and s.riskcatname is not null and r.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid) and ( s.riskstatus !=0 or s.riskstatus is null)
and s.unit=#{company}
) SELECT name,count(1) as value FROM riskcatlist WHERE rn = 1 group by name;

select t.orgid,o.orgname from ( select s.belongsto as orgid from TBL_RISK_ASSPLAN_RISK r left join TBL_RISK_RISKMARKING a on a.assriskid=r.assriskid left join TBL_RISK_ASSPLAN p on p.assplanid=r.assplanid left join TBL_RISK s on s.riskid=r.riskid where s.unit is not null and r.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid) and ( s.riskstatus !=0 or s.riskstatus is null)
and s.unit=#{company}
and a.asssatus=2 group by s.belongsto ) t left join TBL_ORGANIZATION o on o.orgid=t.orgid

select count(1) from TBL_RISK_ASSPLAN_RISK r left join TBL_RISK_RISKMARKING a on a.assriskid=r.assriskid left join TBL_RISK_ASSPLAN p on p.assplanid=r.assplanid left join TBL_RISK s on s.riskid=r.riskid where 1=1 and s.unit is not null and p.unit is not null and r.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid) and ( s.riskstatus !=0 or s.riskstatus is null)
and s.belongsto=#{orgid}
and a.risklevel=#{level}
and a.asssatus=2

select count(1) from TBL_RISK_ASSPLAN_RISK r left join TBL_RISK_RISKMARKING a on a.assriskid=r.assriskid left join TBL_RISK_ASSPLAN p on p.assplanid=r.assplanid left join TBL_RISK s on s.riskid=r.riskid where 1=1 and s.unit is not null and p.unit is not null
and s.unit=#{company}
and a.risklevel=#{level}
and a.asssatus=2

SELECT COUNT(1) FROM TBL_RISK WHERE 
RISKLEVEL =#{yiban} 

AND UNIT=#{orgid}

SELECT COUNT(1) FROM TBL_RISK where
RISKLEVEL =#{zhongda}

AND UNIT=#{orgid}

WITH pgrl(assplanid,riskid,frequency,severity,rn) AS ( 
SELECT p.ASSPLANID,p.RISKID,c.Frequency,c.Severity,ROW_NUMBER() OVER (PARTITION BY p.riskid ORDER BY c.assdate DESC) AS rn FROM  
    TBL_RISK_ASSPLAN_RISK p left JOIN  TBL_RISK_RISKMARKING  c ON p.assriskid = c.assriskid left join tbl_risk r
     on r.riskid=p.riskid    where 1=1 and r.unit is not null 

       and  c.asssatus=#{value} 


     and r.unit=#{orgid}

     ) SELECT  * FROM pgrl WHERE  rn = 1

WITH pgrl(assplanid,riskid,frequency,severity,rn) AS ( SELECT p.ASSPLANID,p.RISKID,c.Frequency,c.Severity,
ROW_NUMBER() OVER (PARTITION BY p.riskid ORDER BY c.assdate DESC) AS rn FROM  TBL_RISK_ASSPLAN_RISK p 
left JOIN  TBL_RISK_RISKMARKING  c ON p.assriskid = c.assriskid left join tbl_risk r on r.riskid=p.riskid 
where r.unit is not null and  c.asssatus=2 and r.riskstatus=0 

and r.unit=#{orgid}

  ) SELECT  * FROM pgrl WHERE  rn = 1
